/* Mixed lookup list for FAQ "linked to" (categories + services). */
function loadRefs() {
  return Promise.all([loadSource('categories'), loadSource('services')]).then(function (r) {
    SOURCES.refs = r[0].map(function (c) { return { id: c.id, name: '▸ ' + tf(c, 'title') }; })
      .concat(r[1].map(function (s) { return { id: s.id, name: tf(s, 'title') }; }));
    return SOURCES.refs;
  });
}
var _loadSource = loadSource;
loadSource = function (entity) { return entity === 'refs' ? loadRefs() : _loadSource(entity); };

/* ---- Service: per-language long content (ServiceTranslations) ------------------- */
function serviceContentEditor(svc, host, editable) {
  host.innerHTML = '<div class="card stack"><h2>' + esc(t('ui.contentPerLang')) + '</h2><p class="small muted">' + esc(t('ui.contentHint')) + '</p>' +
    langTabs() + '<div id="svc-content"><div class="skeleton" style="height:160px"></div></div></div>';
  api('api_admin_list', session.token, 'service_translations', { filters: { service_id: svc.id }, limit: 10 }).then(function (r) {
    var byLang = {};
    r.items.forEach(function (x) { byLang[x.lang] = x; });
    $('#svc-content').innerHTML = LANGS.map(function (l) {
      var x = byLang[l] || {};
      var dir = l === 'ar' ? 'rtl' : 'ltr';
      return '<form class="stack svc-lang" data-ml-lang="' + l + '" data-id="' + esc(x.id || '') + '" novalidate>' +
        [['description', 'f.description'], ['eligibility', 'f.eligibility'], ['procedure', 'f.procedure'], ['required_documents', 'f.requiredDocs'], ['notes', 'f.notes']].map(function (p) {
          return '<div class="field"><label>' + esc(t(p[1])) + ' · ' + l.toUpperCase() + '</label><textarea class="textarea" name="' + p[0] + '" dir="' + dir + '" rows="4">' + esc(x[p[0]] || '') + '</textarea></div>';
        }).join('') +
        (editable ? '<div><button class="btn btn-primary btn-sm" type="submit">' + esc(t('ui.saveLang')) + ' (' + l.toUpperCase() + ')</button></div>' : '') + '</form>';
    }).join('');
    $$('#form-after .lang-tab').forEach(function (b) {
      b.onclick = function () {
        $$('#form-after .lang-tab').forEach(function (x) { x.classList.toggle('active', x === b); });
        $$('.svc-lang').forEach(function (f) { f.hidden = f.getAttribute('data-ml-lang') !== b.getAttribute('data-lang'); });
      };
    });
    $$('#form-after .lang-tab')[0].click();
    if (!editable) $$('.svc-lang textarea').forEach(function (n) { n.disabled = true; });
    $$('.svc-lang').forEach(function (f) {
      f.addEventListener('submit', function (e) {
        e.preventDefault();
        var data = { service_id: svc.id, lang: f.getAttribute('data-ml-lang') };
        $$('textarea', f).forEach(function (ta) { data[ta.name] = ta.value; });
        var existing = f.getAttribute('data-id') || null;
        api('api_admin_save', session.token, 'service_translations', existing, data).then(function (saved) {
          f.setAttribute('data-id', saved.id); toast(t('ui.saved'), 'success');
        }).catch(function (err) { toast(apiMsg(err), 'error'); });
      });
    });
  }).catch(handleApiError);
}

/* ---- Contact message: read-only details under the status form -------------------- */
function contactDetails(rec, host) {
  host.innerHTML = '<div class="card stack"><dl class="dl">' +
    dlRow('f.name', rec.name) + dlRow('f.phone', rec.phone, rec.phone ? 'tel:' + rec.phone : '') + dlRow('f.email', rec.email, rec.email ? 'mailto:' + rec.email : '') +
    dlRow('f.subject', rec.subject) + dlRow('f.createdAt', String(rec.created_at).replace('T', ' ').slice(0, 16)) + '</dl>' +
    '<div class="well"><p dir="auto" style="white-space:pre-wrap;margin:0">' + esc(rec.message) + '</p></div></div>' +
    (canDelete('contacts') && rec.name !== '[anonymised]' ? privacyCard('ct-anon') : '');
  bindPrivacy('ct-anon', 'api_admin_anonymiseContact', rec.id, function () { navigate('#/contacts'); });
}

function dlRow(label, value, href) {
  if (value === '' || value == null) return '';
  return '<dt>' + esc(t(label)) + '</dt><dd>' + (href ? '<a href="' + esc(safeUrl(href)) + '" target="_top" dir="ltr">' + esc(value) + '</a>' : '<span dir="auto">' + esc(value) + '</span>') + '</dd>';
}
